from (values
  ('d40a3de8-43e1-4466-8486-a405940f5c9b'::uuid, 'f9c4258f-0cf6-47c0-86e3-6c563c7c9cb7'::uuid, 'zoho-corporation', 'Member Technical Staff', 'full_time', 'on_campus', 'cse', 2026, '2025-12-01'::date, '{"cgpa":8,"branches":["it","cse","ds","ss","mech"],"backlogs":"no","other":""}'::jsonb, 'Applied through the placement cell portal. Shortlisting was based on CGPA and resume.', 'Aptitude from IndiaBix and previous papers, coding on GeeksforGeeks. I practised explaining my approach out loud, which helped a lot in the interview.', 'Don’t skip aptitude practice. Many strong coders I knew were filtered out in the first round.', 5, 'selected', true, true, 'published', null, null, '2025-09-14T03:28:09.023Z'::timestamptz, 480, false),
  ('cca7b8e0-ab74-4cf4-8aa4-baa6e30f300c'::uuid, '0520bfd8-e1cd-41d0-8692-7d722fccf222'::uuid, 'zoho-corporation', 'Member Technical Staff', 'full_time', 'on_campus', 'ss', 2026, '2025-10-01'::date, null, 'Applied through the placement cell portal. Shortlisting was based on CGPA and resume.', 'I followed a fixed plan for about 3 months: one DSA topic a week on LeetCode, revising **OS, DBMS and CN** from class notes on weekends. Two weeks before the drive I switched to timed mock tests and company-tagged problems.', 'Don’t skip aptitude practice. Many strong coders I knew were filtered out in the first round.', 4, 'selected', false, false, 'published', null, null, '2026-01-01T19:28:09.023Z'::timestamptz, 661, false),
  ('c3a5da11-a755-459c-8647-e290b4fdca6a'::uuid, '11111111-1111-4111-8111-111111111111'::uuid, 'zoho-corporation', 'Software Developer Intern', 'internship', 'on_campus', 'cse', 2027, '2026-08-01'::date, '{"cgpa":8,"branches":["ss","it","mech"],"backlogs":"no","other":""}'::jsonb, 'Applied through the placement cell portal. Shortlisting was based on CGPA and resume.', 'I followed a fixed plan for about 3 months: one DSA topic a week on LeetCode, revising **OS, DBMS and CN** from class notes on weekends. Two weeks before the drive I switched to timed mock tests and company-tagged problems.', 'Trace your approach out loud before coding. They cared more about the brute-force → optimal journey than the final answer.', 3, 'awaiting', false, false, 'published', null, null, '2026-04-20T20:28:09.023Z'::timestamptz, 428, false),
  ('38c17bb2-e893-4e73-8b30-d510c4e0fb3d'::uuid, '52d78d2d-fcf0-46af-837d-0f49a17f9943'::uuid, 'zoho-corporation', 'Member Technical Staff', 'intern_fte', 'on_campus', 'it', 2025, '2024-07-01'::date, null, 'Applied through the placement cell portal. Shortlisting was based on CGPA and resume.', 'Aptitude from IndiaBix and previous papers, coding on GeeksforGeeks. I practised explaining my approach out loud, which helped a lot in the interview.', 'Trace your approach out loud before coding. They cared more about the brute-force → optimal journey than the final answer. Prepare 3–4 stories (conflict, failure, leadership, learning) for behavioural questions using the STAR format.', 4, 'not_selected', false, false, 'published', null, null, '2026-05-26T14:28:09.023Z'::timestamptz, 295, true),
  ('c6059a9f-81bf-4ec5-8062-a2e71dc5bc0b'::uuid, '0520bfd8-e1cd-41d0-8692-7d722fccf222'::uuid, 'zoho-corporation', 'Member Technical Staff', 'full_time', 'on_campus', 'ss', 2026, '2025-11-01'::date, '{"cgpa":7,"branches":["ss","cse","mech","eee","it"],"backlogs":"no","other":""}'::jsonb, 'Applied through the placement cell portal. Shortlisting was based on CGPA and resume.', 'Core subjects from NPTEL lectures and our department notes, plus solving previous GATE questions for the technical round.', 'Practise writing code without autocomplete. The offline round had no IDE support.', 3, 'selected', false, false, 'published', null, 'Fictional demo data: another interview for the same drive', '2026-01-09T22:28:09.023Z'::timestamptz, 824, false),
  ('34551e69-d1ad-464c-8456-622b4fa82a61'::uuid, '5d3f13dd-51f2-4cca-89bc-92be7d7243a6'::uuid, 'zoho-corporation', 'Software Developer Intern', 'internship', 'on_campus', 'ece', 2026, '2025-09-01'::date, '{"cgpa":6.5,"branches":["ece","it","cse"],"backlogs":"no","other":""}'::jsonb, 'Applied through the placement cell portal. Shortlisting was based on CGPA and resume.', 'Focused heavily on my projects: I could explain every design choice and what I would do differently. DSA practice was medium-level problems on arrays, strings and trees.', 'Trace your approach out loud before coding. They cared more about the brute-force → optimal journey than the final answer.', 3, 'selected', false, false, 'hidden', 'Auto-hidden after 3 reports', null, '2026-09-18T12:28:09.023Z'::timestamptz, 257, false),
